import{_ as a}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as r,o as t,c as n,a3 as l}from"./chunks/framework.D1iekJsc.js";const p=JSON.parse('{"title":"Willkommen","description":"MiniTavern Ultra Handbuch — Charakterkarten in einem Satz oder v2/v3, GPT, Claude, OpenRouter oder lokal, Lorebook, Regex, Presets, Bilderkennung und Bildantworten, Backup und Chat-Archive.","frontmatter":{"title":"Willkommen","description":"MiniTavern Ultra Handbuch — Charakterkarten in einem Satz oder v2/v3, GPT, Claude, OpenRouter oder lokal, Lorebook, Regex, Presets, Bilderkennung und Bildantworten, Backup und Chat-Archive.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Willkommen · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra Handbuch — Charakterkarten in einem Satz oder v2/v3, GPT, Claude, OpenRouter oder lokal, Lorebook, Regex, Presets, Bilderkennung und Bildantworten, Backup und Chat-Archive."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de"}]]},"headers":[],"relativePath":"de/index.md","filePath":"de/index.md","lastUpdated":1792058564000}'),i={name:"de/index.md"};function o(d,e,s,u,h,g){return t(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="willkommen" tabindex="-1">Willkommen <a class="header-anchor" href="#willkommen" aria-label="Permalink to &quot;Willkommen&quot;">​</a></h1><div class="overview-hero"><p><img src="'+a+'" alt="MiniTavern Ultra"></p></div><h2 id="uber-die-app" tabindex="-1">Über die App <a class="header-anchor" href="#uber-die-app" aria-label="Permalink to &quot;Über die App&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong> ist eine <strong>AI-Rollenspiel-Chat-App</strong>.</p><p><strong>Begleiter erschaffen. Geschichte spielen.</strong> — ein Satz erzeugt die Karte, oder Sie bringen v2 / v3 mit.</p><p>GPT, Claude, OpenRouter und lokale Modelle zu Hause lassen sich anbinden. Schlüssel bleiben auf dem Telefon, Chats zuerst auf dem Gerät.</p><h2 id="was-sie-tun-konnen" tabindex="-1">Was Sie tun können <a class="header-anchor" href="#was-sie-tun-konnen" aria-label="Permalink to &quot;Was Sie tun können&quot;">​</a></h2><ol><li><p><strong>Ein Satz, oder eine v2- / v3-Karte</strong><br> Beschreiben Sie, wen Sie wollen. Name, Persona und Begrüßung prüfen, dann chatten. Siehe <a href="/ultra_guides/de/manual/ai-create">Mit KI erstellen</a>. PNG / JSON folgen Charakterkarten v2 und v3 — <a href="/ultra_guides/de/manual/chara-card">Charakterkarten</a>.</p></li><li><p><strong>GPT, Claude, OpenRouter oder lokal</strong><br> Eigener Schlüssel, oder Ollama / LM Studio. Schlüssel liegen im sicheren Speicher des Geräts. Siehe <a href="/ultra_guides/de/manual/model-link">Modellverbindung</a>. Ohne bezahltes Kontingent: <a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud</a>; lokal: <a href="/ultra_guides/de/local/">Lokale Modelle</a>.</p></li><li><p><strong>Lorebook, Regex, Presets — anlegen oder importieren</strong><br><a href="/ultra_guides/de/manual/lorebook">Lorebook</a> hält das Setting, <a href="/ultra_guides/de/manual/regex">Regex</a> formt die Ansicht, <a href="/ultra_guides/de/manual/presets">Presets</a> tauschen das Prompt-Layout. Selbst schreiben oder vorhandene Dateien importieren. Sampling bleibt in den Modelleinstellungen.</p></li><li><p><strong>Immersiver Chat: sehen, erkennen, mit Bild antworten</strong><br> Gesendete Fotos können gelesen werden, Personen darauf erkannt. Charaktere antworten mit einem Bild zur Szene. Siehe <a href="/ultra_guides/de/manual/chat">Chat</a>.</p></li><li><p><strong>Backup und Chat-Archive</strong><br> Ein <a href="/ultra_guides/de/manual/backup">Vollbackup</a> nimmt Charaktere, Chats, Lorebooks und Regex mit — ob Schlüssel dabei sind, entscheiden Sie. Ein <a href="/ultra_guides/de/manual/chat-archive">Chat-Archiv</a> lässt sich mergen oder als neuen Chat öffnen.</p></li></ol><h2 id="warum-minitavern" tabindex="-1">Warum MiniTavern <a class="header-anchor" href="#warum-minitavern" aria-label="Permalink to &quot;Warum MiniTavern&quot;">​</a></h2><ul><li><strong>Karten gehen schnell</strong>: ein Satz, oder v2 / v3 importieren</li><li><strong>Ihr Modell</strong>: GPT, Claude, OpenRouter oder lokal — Schlüssel auf dem Gerät</li><li><strong>Werkzeuge für lange Arcs</strong>: Lorebook, Regex, Presets, Persona</li><li><strong>Der Chat sieht</strong>: Fotos, Personen und Bildantworten</li><li><strong>Daten mitnehmen</strong>: Vollbackup und Einzelchat-Archive</li></ul><h2 id="schnellstart" tabindex="-1">Schnellstart <a class="header-anchor" href="#schnellstart" aria-label="Permalink to &quot;Schnellstart&quot;">​</a></h2><ol><li><strong>Modell</strong>: Einstellungen → <a href="/ultra_guides/de/manual/model-link">Modellverbindung</a> → Neu, testen, Standard.</li><li><strong>Charakter</strong>: Charakterkarten → <a href="/ultra_guides/de/manual/chara-card">importieren oder erstellen</a>.</li><li><strong>Chatten</strong>: vom Charakter aus — Begleitung oder Rolle, Ihre Wahl.</li></ol><p>Details: <a href="/ultra_guides/de/manual/getting-started">Erste Schritte</a>. Lokal: <a href="/ultra_guides/de/local/">Übersicht</a> · <a href="/ultra_guides/de/quickstart">Sprach-Quickstart</a> · <a href="/ultra_guides/de/local/image-gen/">Bild</a>. Free: <a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud</a>.</p><h2 id="handbuch-einstiege" tabindex="-1">Handbuch-Einstiege <a class="header-anchor" href="#handbuch-einstiege" aria-label="Permalink to &quot;Handbuch-Einstiege&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Hinweis</th></tr></thead><tbody><tr><td><a href="/ultra_guides/de/manual/">Handbuch</a></td><td>Lesereihenfolge und Überblick</td></tr><tr><td><a href="/ultra_guides/de/manual/model-link">Modelle</a></td><td>Verbindung, Parameter, Test, Fehler</td></tr><tr><td><a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud</a></td><td>Free-/Trial-Kontingente und Key-Eintrag</td></tr><tr><td><a href="/ultra_guides/de/local/">Lokale Modelle</a></td><td>Sprache / Bild lokal</td></tr><tr><td><a href="/ultra_guides/de/manual/chara-card">Charaktere</a> · <a href="/ultra_guides/de/manual/ai-create">Mit KI erstellen</a></td><td>Import, Bearbeiten, Chatstart, aus Beschreibung erzeugen</td></tr><tr><td><a href="/ultra_guides/de/manual/chat">Chat</a> · <a href="/ultra_guides/de/manual/bubbles">Blasen und Eingabe</a></td><td>Dialog, Aussehen, Session</td></tr><tr><td><a href="/ultra_guides/de/manual/lorebook">Fortgeschritten</a> · <a href="/ultra_guides/de/manual/presets">Presets</a></td><td>Lorebook, Regex, Persona, Presets</td></tr></tbody></table><p>In der App: Einstellungen → <strong>Hilfe &amp; Feedback</strong> → <strong>Benutzerhandbuch</strong>.</p><h2 id="faq-kurz" tabindex="-1">FAQ (Kurz) <a class="header-anchor" href="#faq-kurz" aria-label="Permalink to &quot;FAQ (Kurz)&quot;">​</a></h2><p><strong>Q: Was ist MiniTavern Ultra?</strong><br> A: Eine AI-Roleplay-Chat-App. Karte in einem Satz oder v2 / v3 importieren; GPT, Claude, OpenRouter oder lokales Modell. Schlüssel und Chats bleiben zuerst auf dem Gerät.</p><p><strong>Q: Werden Daten auf eure Server hochgeladen?</strong><br> A: Chat, Charaktere und Schlüssel bleiben standardmäßig auf dem Gerät; Modell-Requests gehen an Ihre konfigurierten Dritt- oder Lokaladressen. Siehe <a href="/ultra_guides/de/privacy">Datenschutz</a>.</p><p><strong>Q: Geht es ohne API?</strong><br> A: Cloud-Key selbst beschaffen oder nach <a href="/ultra_guides/de/local/">Lokale Modelle</a> am PC aufsetzen und das Handy verbinden. Free: <a href="/ultra_guides/de/free-cloud/">Kostenlose Cloud</a>; lokales Bild: <a href="/ultra_guides/de/local/image-gen/">Bildmodelle</a>.</p><h2 id="download-rechtliches" tabindex="-1">Download &amp; Rechtliches <a class="header-anchor" href="#download-rechtliches" aria-label="Permalink to &quot;Download &amp; Rechtliches&quot;">​</a></h2><ul><li>Kopfzeile <strong>MiniTavern herunterladen</strong> · <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">Produktwebsite</a></li><li><a href="/ultra_guides/de/privacy">Datenschutz</a> · <a href="/ultra_guides/de/terms">Nutzungsbedingungen</a></li></ul>',22)])])}const b=r(i,[["render",o]]);export{p as __pageData,b as default};
